#include "virtual_broadcast/broadcaster/epg.hpp"
#include "virtual_broadcast/broadcaster/si.hpp"
#include <algorithm>
#include <map>
#include <stdexcept>

namespace vb { namespace {
void Put16(std::vector<std::uint8_t>&b,std::uint16_t v){b.push_back(static_cast<std::uint8_t>(v>>8));b.push_back(static_cast<std::uint8_t>(v));}
std::vector<std::uint8_t>EventBytes(const EpgEvent&e,RunningStatus status,const AribStringEncoder&encoder){auto desc=EventDescriptorWriter::Short(encoder,e.title,e.short_description);const auto start=MjdTimeEncoder::EncodeJst(e.start_time);const auto duration=DurationEncoder::Encode(e.duration);std::vector<std::uint8_t>b;Put16(b,e.event_id);b.insert(b.end(),start.begin(),start.end());b.insert(b.end(),duration.begin(),duration.end());const auto n=static_cast<std::uint16_t>(desc.size());b.push_back(static_cast<std::uint8_t>((static_cast<std::uint8_t>(status)<<5)|(e.free_ca_mode?0x10:0)|(n>>8)));b.push_back(static_cast<std::uint8_t>(n));b.insert(b.end(),desc.begin(),desc.end());return b;}
std::vector<std::uint8_t>Section(std::uint8_t tid,std::uint16_t sid,std::uint16_t tsid,std::uint16_t onid,std::uint8_t version,std::uint8_t sn,std::uint8_t last,std::uint8_t seglast,std::uint8_t lasttid,std::span<const std::vector<std::uint8_t>>events){std::vector<std::uint8_t>b{tid,0xf0,0};Put16(b,sid);b.push_back(static_cast<std::uint8_t>(0xc1|((version&31)<<1)));b.push_back(sn);b.push_back(last);Put16(b,tsid);Put16(b,onid);b.push_back(seglast);b.push_back(lasttid);for(const auto&e:events)b.insert(b.end(),e.begin(),e.end());const auto length=b.size()+4-3;if(length>4093)throw std::length_error("EIT section too large");b[1]=static_cast<std::uint8_t>(0xf0|(length>>8));b[2]=static_cast<std::uint8_t>(length);const auto crc=MpegCrc32(b);b.push_back(crc>>24);b.push_back(crc>>16);b.push_back(crc>>8);b.push_back(crc);return b;}
}
std::vector<std::vector<std::uint8_t>>EitPresentFollowingGenerator::Generate(const EpgSchedule&s,std::chrono::sys_seconds now,std::uint16_t sid,std::uint16_t tsid,std::uint16_t onid,const AribStringEncoder&e,std::uint8_t version){const auto[p,f]=s.PresentFollowing(now);std::vector<std::vector<std::uint8_t>>out;for(std::uint8_t sn=0;sn<2;++sn){std::vector<std::vector<std::uint8_t>>events;const auto*x=sn?f:p;if(x)events.push_back(EventBytes(*x,sn?RunningStatus::NotRunning:RunningStatus::Running,e));out.push_back(Section(kTableIdEitPfActual,sid,tsid,onid,version,sn,1,1,kTableIdEitPfActual,events));}return out;}
std::vector<std::vector<std::uint8_t>>EitScheduleGenerator::Generate(const EpgSchedule&s,std::chrono::sys_seconds now,std::uint16_t sid,std::uint16_t tsid,std::uint16_t onid,const AribStringEncoder&e,std::uint8_t version){using namespace std::chrono;const auto t0=floor<days>(now+9h);struct Slot{std::vector<std::vector<std::uint8_t>>events;};std::map<int,std::map<int,Slot>>tables;int max_table=0;for(const auto&event:s.events()){const auto local=event.start_time+9h;if(local<sys_seconds{t0})continue;const auto hours_from=duration_cast<hours>(local-sys_seconds{t0}).count();const int table=static_cast<int>(hours_from/96);if(table>15)continue;const int segment=static_cast<int>((hours_from%96)/3);tables[table][segment].events.push_back(EventBytes(event,RunningStatus::Undefined,e));max_table=std::max(max_table,table);}const auto last_tid=static_cast<std::uint8_t>(0x50+max_table);std::vector<std::vector<std::uint8_t>>out;for(int table=0;table<=max_table;++table){const auto max_seg=tables[table].empty()?0:tables[table].rbegin()->first;struct Chunk{int segment;std::vector<std::vector<std::uint8_t>>events;};std::vector<Chunk>chunks;for(int seg=0;seg<=max_seg;++seg){Chunk current{seg,{}};std::size_t bytes=0;for(auto&event:tables[table][seg].events){if(!current.events.empty()&&bytes+event.size()>4000-18){chunks.push_back(std::move(current));current=Chunk{seg,{}};bytes=0;}current.events.push_back(event);bytes+=event.size();}chunks.push_back(std::move(current));}const auto last_section=static_cast<std::uint8_t>(max_seg*8+std::count_if(chunks.begin(),chunks.end(),[&](const auto&c){return c.segment==max_seg;})-1);for(std::size_t i=0;i<chunks.size();){const int seg=chunks[i].segment;std::size_t j=i;while(j<chunks.size()&&chunks[j].segment==seg)++j;if(j-i>8)throw std::length_error("EIT segment needs more than 8 sections");const auto seglast=static_cast<std::uint8_t>(seg*8+(j-i)-1);for(std::size_t part=i;part<j;++part){const auto sn=static_cast<std::uint8_t>(seg*8+(part-i));out.push_back(Section(static_cast<std::uint8_t>(0x50+table),sid,tsid,onid,version,sn,last_section,seglast,last_tid,chunks[part].events));}i=j;}}return out;}
}
